<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<style>
*,*:before,*:after{box-sizing:border-box;margin:0;padding:0;}
html,body{width:1920px;height:1080px;overflow:hidden;font-size:10px;}
newspaper-ending{
paper:#e6dfcf;--paper-light:#f2ecdf
ink:#171816;--muted:#686459;--accent:#9f2026
position:absolute;inset:0;overflow:hidden;color:var(--ink)
background
repeating-linear-gradient(0deg,rgba(25,24,20,.025) 0,rgba(25,24,20,.025) 1px,transparent 1px,transparent 4px)
radial-gradient(circle at 20% 10%,var(--paper-light),var(--paper) 72%)
font-family:Arial,sans-serif
}
newspaper-ending::before{
content:"";position:absolute;inset:22px
border:1px solid rgba(23,24,22,.32);pointer-events:none;z-index:0
}
/* MASTHEAD */
news-masthead{
position:absolute;top:50px;left:72px;right:72px;height:112px
display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:28px
border-top:5px solid var(--ink);border-bottom:2px solid var(--ink)
z-index:20
}
news-masthead>span{font-size:13px;font-weight:700;letter-spacing:.2em;}
news-masthead>span:last-child{text-align:right;}
news-masthead>strong{
font-family:Georgia,"Times New Roman",serif
font-size:44px;line-height:1;letter-spacing:-.035em;text-align:center
}
/* BODY — centered layout, no photo */
newspaper-body{
position:absolute
top:180px;left:72px;right:72px;bottom:80px
display:flex;flex-direction:column
align-items:center
justify-content:center
z-index:5
}
news-kicker{
margin:0 0 60px;color:var(--accent)
font-size:15px;font-weight:800;letter-spacing:.22em
text-align:center
}
/* TIMELINE — full width, centered */
career-timeline{
position:relative
width:100%
height:340px
display:grid
grid-template-columns:repeat(5,1fr)
align-items:center
}
timeline-rule{
position:absolute;left:5%;right:5%;top:168px;height:3px
background:var(--ink);transform:scaleX(0);transform-origin:left center
z-index:10
}
timeline-rule::after{
content:"";position:absolute;left:0;bottom:-6px;width:100%;height:1px
background:rgba(23,24,22,.35)
}
milestone{
position:relative;height:340px
display:flex;flex-direction:column
align-items:center
padding-top:20px
text-align:center
opacity:0;transform:translateY(16px);z-index:10
}
/* dot at vertical center of timeline */
milestone::after{
content:""
position:absolute
top:155px
width:18px;height:18px
border:3px solid var(--paper);border-radius:50%
background:var(--ink)
transform:translateX(0)
box-shadow:0 0 0 2px var(--ink)
}
milestone time{
display:block
font-family:Georgia,"Times New Roman",serif
font-size:58px; /* larger year number */
font-weight:700;line-height:1
}
milestone strong{
display:block;margin-top:16px
font-size:18px;letter-spacing:.14em
}
milestone small{
display:block;margin-top:60px
color:var(--muted);font-size:40px;font-weight:700
line-height:1.2;letter-spacing:.08em;text-transform:uppercase
}
milestone-latest time,.milestone-latest strong{color:var(--accent);}
milestone-latest::after{background:var(--accent);box-shadow:0 0 0 2px var(--accent);}
/* FOOTER */
news-footer{
position:absolute;left:72px;right:72px;bottom:32px
display:flex;justify-content:space-between;padding-top:12px
border-top:2px solid var(--ink)
font-size:12px;font-weight:800;letter-spacing:.24em
z-index:10
}
/* FINAL LOCKUP */
final-lockup{
position:absolute;inset:0;display:grid;place-content:center
text-align:center;opacity:0;visibility:hidden;z-index:30
background:var(--paper)
}
final-lockup span{color:var(--accent);font-size:14px;font-weight:800;letter-spacing:.3em;}
final-lockup h2{
margin:18px 0;font-family:Georgia,"Times New Roman",serif
font-size:92px;line-height:.82;letter-spacing:-.055em
}
final-lockup i{
display:block;width:480px;height:3px;margin:10px auto 18px
background:var(--ink);transform:scaleX(0)
}
final-lockup p{margin:0;font-size:16px;font-weight:800;letter-spacing:.28em;}
#open-fade,#close-fade{position:absolute;inset:0;z-index:100;background:#000;pointer-events:none;}
#open-fade{opacity:1;}#close-fade{opacity:0;}
</style>
</head>
<body>
<div id="open-fade"></div>
<div id="close-fade"></div>
<section class="newspaper-ending">
<header class="news-masthead">
<span>THE ACTOR'S RECORD</span>
<strong>BENEDICT CUMBERBATCH</strong>
<span>LONDON · 2026</span>
</header>
<div class="newspaper-body">
<p class="news-kicker">A CAREER IN FIVE ACTS</p>
<div class="career-timeline">
<div class="timeline-rule"></div>
<article class="milestone"><time>2004</time><strong>HAWKING</strong><small>BBC</small></article>
<article class="milestone"><time>2010</time><strong>SHERLOCK</strong><small>BBC</small></article>
<article class="milestone"><time>2014</time><strong>TURING</strong><small>FILM</small></article>
<article class="milestone"><time>2015</time><strong>HAMLET</strong><small>STAGE</small></article>
<article class="milestone milestone-latest"><time>2026</time><strong>EARTH</strong><small>NOW</small></article>
</div>
</div>
<footer class="news-footer">
<span>STAGE</span><span>SCREEN</span><span>VOICE</span><span>LEGACY</span>
</footer>
<div class="final-lockup">
<span>THE STORY CONTINUES</span>
<h2>BENEDICT<br>CUMBERBATCH</h2>
<i></i>
<p>STILL EVOLVING</p>
</div>
</section>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
tl.to('#open-fade',{opacity:0,duration:0.4,ease:'power2.out'},0.0)
/* rule draws */
tl.to('.timeline-rule',{scaleX:1,duration:0.8,ease:'power3.inOut'},0.0)
/* milestones stagger in */
tl.fromTo('.milestone'
{y:16,autoAlpha:0}
{y:0,autoAlpha:1,duration:0.42,stagger:0.48,ease:'power3.out'}
0.8
)
/* highlight latest */
tl.to('.milestone:not(.milestone-latest)',{autoAlpha:0.22,duration:0.4},3.5)
tl.to('.milestone-latest',{scale:1.1,transformOrigin:'center center',duration:0.55,ease:'power3.out'},3.5)
/* final lockup */
tl.to('.newspaper-body, .news-masthead',{autoAlpha:0,duration:0.38,ease:'power2.in'},7.3)
tl.fromTo('.final-lockup'
{y:22,autoAlpha:0}
{y:0,autoAlpha:1,duration:0.65,ease:'power4.out'
onStart:function(){gsap.set('.final-lockup',{visibility:'visible'});}}
7.45
)
tl.to('.final-lockup i',{scaleX:1,duration:0.55,ease:'power3.out'},7.75)
tl.to('#close-fade',{opacity:1,duration:0.5,ease:'power2.inOut'},8.6)
tl.set('#close-fade',{opacity:1},9.0)
})
</script>
</body>
</html>
